@st.cache_data(
    ttl=300,
    show_spinner=False,
)
def load_geometry_market_scan(
    timeframe,
    candle_limit,
):
    result = (
        geometry_market_scanner_service
        .scan_market(
            timeframe=timeframe,
            candle_limit=candle_limit,
        )
    )

    diagnostics = dict(
        geometry_market_scanner_service
        .last_diagnostics
    )

    error = (
        geometry_market_scanner_service
        .last_error
    )

    return (
        result,
        diagnostics,
        error,
    )
    
def render_geometry_observation_form(
    symbol,
    timeframe,
    candidate,
    candles,
    scanner_parameters,
    source,
    widget_prefix,
):
    if hasattr(candidate, "to_dict"):
        candidate_dict = (
            candidate.to_dict()
        )
    else:
        candidate_dict = dict(
            candidate
        )

    raw_status = candidate_dict.get(
        "status"
    )

    if (
        raw_status is not None
        and pd.notna(raw_status)
    ):
        status = str(
            raw_status
        ).upper()
    else:
        status = (
            "BREAKOUT"
            if bool(
                candidate_dict.get(
                    "breakout_detected",
                    False,
                )
            )
            else "FORMING"
        )

    already_saved = (
        geometry_observation_journal
        .contains(
            symbol=symbol,
            timeframe=timeframe,
            candidate=candidate_dict,
        )
    )

    st.markdown("#### 💾 Review & Save")

    st.caption(
        "Congela la figura, sus velas, "
        "parámetros y contexto Market Flow 4h."
    )

    if already_saved:
        st.info(
            "Esta figura ya fue guardada "
            f"en estado {status}."
        )

    form_key = (
        f"{widget_prefix}_"
        f"{symbol}_"
        f"{candidate_dict.get('geometry')}_"
        f"{candidate_dict.get('start_timestamp')}_"
        f"{status}"
    )

    with st.form(
        key=f"geometry_review_{form_key}"
    ):
        review_1, review_2 = (
            st.columns(2)
        )

        with review_1:
            figure_quality = st.selectbox(
                "Figure quality",
                options=[
                    "GOOD",
                    "UNCERTAIN",
                    "BAD",
                ],
                index=0,
                key=(
                    f"figure_quality_{form_key}"
                ),
            )

        with review_2:
            if status == "BREAKOUT":
                breakout_options = [
                    "GOOD",
                    "WEAK",
                    "FALSE_BREAKOUT",
                    "UNCERTAIN",
                ]
            else:
                breakout_options = [
                    "PENDING",
                    "NOT_APPLICABLE",
                ]

            breakout_quality = st.selectbox(
                "Breakout quality",
                options=breakout_options,
                index=0,
                key=(
                    f"breakout_quality_"
                    f"{form_key}"
                ),
            )

        review_notes = st.text_area(
            "Notes",
            placeholder=(
                "Qué te gustó o no de la "
                "figura, breakout, volumen, "
                "entrada potencial, etc."
            ),
            key=f"notes_{form_key}",
        )

        save_observation = (
            st.form_submit_button(
                "💾 Save observation",
                disabled=already_saved,
                use_container_width=True,
            )
        )

    if not save_observation:
        return

    review_timestamp = int(
        pd.Timestamp.now(
            tz="UTC"
        ).timestamp()
        * 1000
    )

    market_flow_at_review = (
        get_geometry_market_flow_context(
            symbol=symbol,
            reference_timestamp=(
                review_timestamp
            ),
        )
    )

    breakout_timestamp = (
        candidate_dict.get(
            "breakout_timestamp"
        )
    )

    if (
        breakout_timestamp is not None
        and pd.notna(
            breakout_timestamp
        )
    ):
        breakout_timestamp = int(
            breakout_timestamp
        )

        possible_breakout_context = (
            get_geometry_market_flow_context(
                symbol=symbol,
                reference_timestamp=(
                    breakout_timestamp
                ),
            )
        )

        if (
            possible_breakout_context.get(
                "available"
            )
            and possible_breakout_context.get(
                "temporal_relation"
            )
            == "AVAILABLE_AT_REFERENCE"
        ):
            market_flow_at_breakout = (
                possible_breakout_context
            )
        else:
            market_flow_at_breakout = {
                "available": False,
                "reason": (
                    "historical_snapshot_unavailable"
                ),
                "symbol": symbol,
                "reference_timestamp": (
                    breakout_timestamp
                ),
                "checked_snapshot": (
                    possible_breakout_context
                ),
            }

    else:
        market_flow_at_breakout = {
            "available": False,
            "reason": "breakout_not_observed",
            "symbol": symbol,
        }

    saved = (
        geometry_observation_journal
        .save(
            symbol=symbol,
            timeframe=timeframe,
            candidate=candidate_dict,
            candles=candles,
            scanner_parameters=(
                scanner_parameters
            ),
            source=source,
            figure_quality=(
                figure_quality
            ),
            breakout_quality=(
                breakout_quality
            ),
            notes=review_notes,
            market_flow_at_review=(
                market_flow_at_review
            ),
            market_flow_at_breakout=(
                market_flow_at_breakout
            ),
        )
    )

    if saved is None:
        if (
            geometry_observation_journal
            .last_error
            == "duplicate_observation"
        ):
            st.warning(
                "La observación ya estaba "
                "guardada."
            )
        else:
            st.error(
                "No se pudo guardar: "
                f"{geometry_observation_journal.last_error}"
            )

        return

    st.success(
        "Observation saved · "
        f"{saved['observation_id']}"
    )
    
def get_geometry_market_flow_context(
    symbol,
    reference_timestamp,
):
    snapshot = (
        market_flow_dashboard_service
        .get_snapshot(
            timeframe="4h"
        )
    )

    if snapshot is None:
        return {
            "available": False,
            "reason": (
                market_flow_dashboard_service
                .last_error
                or "snapshot_unavailable"
            ),
            "symbol": symbol,
            "reference_timestamp": (
                reference_timestamp
            ),
        }

    context = (
        market_flow_dashboard_service
        .get_symbol_context(
            snapshot=snapshot,
            symbol=symbol,
            reference_timestamp=(
                reference_timestamp
            ),
        )
    )

    if context is None:
        return {
            "available": False,
            "reason": (
                market_flow_dashboard_service
                .last_error
                or "symbol_context_unavailable"
            ),
            "symbol": symbol,
            "reference_timestamp": (
                reference_timestamp
            ),
        }

    return context

def format_geometry_metric(
    value,
    suffix="",
    decimals=2,
):
    if (
        value is None
        or pd.isna(value)
    ):
        return "—"

    return (
        f"{float(value):.{decimals}f}"
        f"{suffix}"
    )


def render_breakout_quality_metrics(
    candidate,
):
    if hasattr(candidate, "to_dict"):
        candidate = candidate.to_dict()
    else:
        candidate = dict(candidate)

    breakout_detected = bool(
        candidate.get(
            "breakout_detected",
            False,
        )
    )

    st.markdown(
        "#### Breakout quality"
    )

    if not breakout_detected:
        st.caption(
            "No breakout has been observed. "
            "Quality metrics are pending."
        )
        return

    row_1 = st.columns(4)

    row_1[0].metric(
        "Breakout score",
        format_geometry_metric(
            candidate.get(
                "breakout_score"
            )
        ),
    )

    row_1[1].metric(
        "Direction",
        candidate.get(
            "breakout_direction"
        )
        or "—",
    )

    row_1[2].metric(
        "Close outside",
        format_geometry_metric(
            candidate.get(
                "breakout_close_distance_pct"
            ),
            suffix="%",
            decimals=4,
        ),
    )

    row_1[3].metric(
        "Body outside",
        format_geometry_metric(
            candidate.get(
                "breakout_body_distance_pct"
            ),
            suffix="%",
            decimals=4,
        ),
    )

    row_2 = st.columns(4)

    row_2[0].metric(
        "Candle body",
        format_geometry_metric(
            candidate.get(
                "breakout_body_pct"
            ),
            suffix="%",
        ),
    )

    row_2[1].metric(
        "Volume ratio",
        format_geometry_metric(
            candidate.get(
                "breakout_volume_ratio"
            ),
            suffix="x",
        ),
    )

    row_2[2].metric(
        "ATR extension",
        format_geometry_metric(
            candidate.get(
                "breakout_atr_extension"
            ),
            suffix=" ATR",
        ),
    )

    row_2[3].metric(
        "Directional close",
        format_geometry_metric(
            candidate.get(
                "breakout_close_location_pct"
            ),
            suffix="%",
        ),
    )

    st.caption(
        "Breakout score measures the observed "
        "rupture quality. It is independent from "
        "the geometry confidence."
    )

def render_pattern_maturity_metrics(
    candidate,
):
    if hasattr(candidate, "to_dict"):
        candidate = candidate.to_dict()
    else:
        candidate = dict(candidate)

    st.markdown(
        "#### Pattern maturity"
    )

    columns = st.columns(4)

    columns[0].metric(
        "Progress to apex",
        format_geometry_metric(
            candidate.get(
                "pattern_progress_pct"
            ),
            suffix="%",
        ),
    )

    columns[1].metric(
        "Bars to apex",
        format_geometry_metric(
            candidate.get(
                "distance_to_apex_bars"
            ),
        ),
    )

    columns[2].metric(
        "Current width",
        format_geometry_metric(
            candidate.get(
                "current_width_pct"
            ),
            suffix="%",
            decimals=4,
        ),
    )

    columns[3].metric(
        "Price position",
        format_geometry_metric(
            candidate.get(
                "current_price_position_pct"
            ),
            suffix="%",
        ),
    )

    progress = candidate.get(
        "pattern_progress_pct"
    )

    if (
        progress is not None
        and pd.notna(progress)
    ):
        progress = float(progress)

        if progress < 40:
            maturity_label = (
                "Early structure"
            )
        elif progress < 60:
            maturity_label = (
                "Developing structure"
            )
        elif progress <= 90:
            maturity_label = (
                "Mature structure"
            )
        elif progress <= 100:
            maturity_label = (
                "Near theoretical apex"
            )
        else:
            maturity_label = (
                "Past theoretical apex"
            )

        st.caption(
            f"Maturity state: "
            f"{maturity_label}. "
            "These ranges are descriptive and "
            "are not entry conditions."
        )

    else:
        st.caption(
            "This geometry has no finite "
            "convergence apex."
        )

@st.cache_data(show_spinner=False)
def load_csv_cached(
    path,
    modified_ns,
):
    path = Path(path)

    if not path.exists():
        return pd.DataFrame()
    
    print(
        f"[DASHBOARD CSV] reading {path} "
        f"mtime={modified_ns}"
    )

    return pd.read_csv(path)

@st.cache_data(show_spinner=False)
def load_parquet_cached(
    path,
    modified_ns,
):
    path = Path(path)

    if not path.exists():
        return pd.DataFrame()

    return pd.read_parquet(path)

def get_file_modified_ns(path):
    path = Path(path)

    if not path.exists():
        return None

    return path.stat().st_mtime_ns

