def timeframe_to_minutes(timeframe):
    mapping = {
        "1m": 1,
        "3m": 3,
        "5m": 5,
        "15m": 15,
        "30m": 30,
        "1h": 60,
        "2h": 120,
        "4h": 240,
    }

    return mapping.get(timeframe, 30)

def format_replay_duration(total_minutes):
    total_minutes = int(total_minutes)

    if total_minutes < 60:
        return f"{total_minutes} min"

    if total_minutes % 60 == 0:
        hours = total_minutes // 60

        if hours == 1:
            return "1 hour"

        return f"{hours} hours"

    hours = total_minutes // 60
    minutes = total_minutes % 60

    return f"{hours}h {minutes}m"


def build_replay_observation_windows(timeframe):
    """
    Builds TP/SL replay observation windows using
    the strategy MAIN / trigger timeframe.

    The structural scale is expressed in candles,
    not fixed clock hours.
    """
    timeframe = str(timeframe or "").strip()

    valid_timeframes = {
        "1m",
        "3m",
        "5m",
        "15m",
        "30m",
        "1h",
        "2h",
        "4h",
    }

    if timeframe not in valid_timeframes:
        timeframe = "30m"

    timeframe_minutes = timeframe_to_minutes(timeframe)

    candle_windows = [
        3,
        6,
        12,
        24,
        48,
    ]

    windows = []

    for candles in candle_windows:
        total_minutes = candles * timeframe_minutes
        duration_label = format_replay_duration(total_minutes)

        windows.append(
            {
                "candles": candles,
                "minutes": total_minutes,
                "label": f"{candles} candles · {duration_label}",
            }
        )

    return windows

def fmt_price_for_display(x, decimals=10):
    if x in (None, "", "N/A"):
        return "-"

    try:
        return f"{float(x):.{decimals}f}".rstrip("0").rstrip(".")
    except Exception:
        return str(x)

@st.cache_data(show_spinner=False)
def load_position_snapshot_cached(
    snapshot_path,
    modified_ns,
):
    snapshot_path = Path(snapshot_path)

    if not snapshot_path.exists():
        return None

    try:
        with open(
            snapshot_path,
            "r",
            encoding="utf-8",
        ) as file:
            return json.load(file)

    except (
        OSError,
        json.JSONDecodeError,
        TypeError,
    ):
        return None
    
def build_open_position_inspector_df(
    open_positions,
    snapshots_dir,
    default_trigger_tf="30m",
):
    if not open_positions:
        return pd.DataFrame()

    snapshots_dir = Path(snapshots_dir)
    rows = []

    for exchange_position in open_positions:
        exchange_position = dict(
            exchange_position
        )

        symbol = str(
            exchange_position.get("symbol", "")
        ).upper()

        position_data = {}
        context_data = {}
        snapshot_available = False

        if symbol:
            snapshot_path = (
                snapshots_dir
                / f"{symbol}.json"
            )

            snapshot = load_position_snapshot_cached(
                snapshot_path,
                get_file_modified_ns(
                    snapshot_path
                ),
            )

            if isinstance(snapshot, dict):
                position_data = (
                    snapshot.get("position")
                    or {}
                )

                context_data = (
                    snapshot.get("context")
                    or position_data.get(
                        "signal_context"
                    )
                    or {}
                )

                snapshot_available = True

        # El exchange prevalece para mark price,
        # quantity y PnL actuales.
        row = {
            **context_data,
            **position_data,
            **exchange_position,
        }

        row["symbol"] = symbol

        row["status"] = "OPEN"

        row["entry_price"] = (
            exchange_position.get("entry_price")
            or position_data.get("real_entry")
            or position_data.get("entry_price")
            or position_data.get("entry")
        )

        row["real_entry"] = (
            position_data.get("real_entry")
            or row["entry_price"]
        )

        row["entry"] = (
            position_data.get("entry")
            or row["entry_price"]
        )

        row["entry_ts"] = (
            position_data.get("entry_ts")
            or position_data.get("opened_ts")
            or context_data.get("entry_ts")
        )

        row["tp"] = (
            position_data.get("tp")
            or exchange_position.get("tp")
        )

        row["sl"] = (
            position_data.get("sl")
            or exchange_position.get("sl")
        )

        row["trigger_tf"] = (
            context_data.get("trigger_tf")
            or default_trigger_tf
        )

        row["_snapshot_available"] = (
            snapshot_available
        )

        rows.append(row)

    return (
        pd.DataFrame(rows)
        .reset_index(drop=True)
    )
    
def normalize_epoch_ms(value):
    if value is None:
        return None

    try:
        if pd.isna(value):
            return None
    except Exception:
        pass

    if isinstance(value, (int, float)):
        numeric_value = int(value)

        # Ya está expresado en milisegundos
        if numeric_value > 10_000_000_000:
            return numeric_value

        # Segundos Unix
        return numeric_value * 1000

    timestamp = pd.to_datetime(
        value,
        utc=True,
        errors="coerce",
    )

    if pd.isna(timestamp):
        return None

    return int(timestamp.timestamp() * 1000)


@st.cache_data(show_spinner=False)
def load_watch_history_cached(
    path,
    modified_ns,
    compression_created_ts,
    limit,
    timezone,
):
    path = Path(path)

    if not path.exists():
        return pd.DataFrame()

    rows = []

    try:
        with path.open(
            "r",
            encoding="utf-8",
        ) as file:
            for line in file:
                line = line.strip()

                if not line:
                    continue

                try:
                    rows.append(
                        json.loads(line)
                    )
                except (
                    json.JSONDecodeError,
                    TypeError,
                ):
                    continue

    except OSError:
        return pd.DataFrame()

    if not rows:
        return pd.DataFrame()

    history_df = pd.DataFrame(rows)

    # Filtrar la watch exacta del trade.
    created_ts_ms = normalize_epoch_ms(
        compression_created_ts
    )

    if (
        created_ts_ms is not None
        and "compression_created_ts"
        in history_df.columns
    ):
        journal_created_ts = pd.to_numeric(
            history_df[
                "compression_created_ts"
            ],
            errors="coerce",
        )

        history_df = history_df.loc[
            journal_created_ts.eq(
                created_ts_ms
            )
        ].copy()

    if history_df.empty:
        return history_df

    # Extraer OHLCV guardado en last_candle.
    if "last_candle" in history_df.columns:
        candle_data = (
            history_df["last_candle"]
            .apply(
                lambda value: (
                    value
                    if isinstance(value, dict)
                    else {}
                )
            )
        )

        for field in [
            "timestamp",
            "open",
            "high",
            "low",
            "close",
            "volume",
            "atr",
        ]:
            history_df[
                f"candle_{field}"
            ] = candle_data.apply(
                lambda candle: candle.get(field)
            )

    if (
        "compression_updated_ts"
        in history_df.columns
    ):
        numeric_updated_ts = pd.to_numeric(
            history_df[
                "compression_updated_ts"
            ],
            errors="coerce",
        )

        history_df["timestamp"] = (
            pd.to_datetime(
                numeric_updated_ts,
                unit="ms",
                utc=True,
                errors="coerce",
            )
            .dt.tz_convert(timezone)
        )

        history_df = (
            history_df.sort_values(
                "compression_updated_ts",
                ascending=True,
            )
        )

    if limit is not None:
        try:
            normalized_limit = int(limit)
        except (TypeError, ValueError):
            normalized_limit = 0

        if normalized_limit > 0:
            history_df = history_df.tail(
                normalized_limit
            )

    return history_df.reset_index(
        drop=True
    )


def load_watch_history(
    symbol,
    compression_created_ts=None,
    base_dir="compression_watch_journal",
    limit=None,
):
    path = (
        Path(base_dir)
        / f"{str(symbol).upper()}.jsonl"
    )

    return load_watch_history_cached(
        path=path,
        modified_ns=get_file_modified_ns(
            path
        ),
        compression_created_ts=(
            compression_created_ts
        ),
        limit=limit,
        timezone=TZ,
    )

