def render_trade_inspector_for_row(
    row,
    status="CLOSED",
    key_prefix="trade_inspector",
):
    inspection = trade_inspector_service.inspect(
        row=row,
        status=status,
    )

    selected_trade = inspection.trade

    inspector_timeframe = str(
        row.get("trigger_tf", "30m") or "30m"
    )

    valid_timeframes = {
        "1m",
        "3m",
        "5m",
        "15m",
        "30m",
        "1h",
        "2h",
        "4h",
    }

    if inspector_timeframe not in valid_timeframes:
        inspector_timeframe = "30m"

    interval_minutes = timeframe_to_minutes(
        inspector_timeframe
    )

    with st.spinner(
        f"Loading {inspector_timeframe} candles "
        f"for {selected_trade.symbol}..."
    ):
        inspection.candles = (
            trade_inspector_service.load_trade_candles(
                trade=selected_trade,
                interval=inspector_timeframe,
                candles_before=20,
                candles_after=12,
            )
        )

    st.markdown("---")

    st.subheader(
        f"🔎 Trade Inspector — {selected_trade.symbol}"
    )

    st.caption(
        f"Inspection timeframe: {inspector_timeframe}"
    )

    c1, c2, c3, c4 = st.columns(4)

    c1.metric(
        "Status",
        selected_trade.status or "-",
    )

    c2.metric(
        "Side",
        selected_trade.side or "-",
    )

    c3.metric(
        "Entry",
        fmt_price_for_display(
            selected_trade.entry_price
        ),
    )

    c4.metric(
        "Exit",
        fmt_price_for_display(
            selected_trade.exit_price
        ),
    )

    c5, c6, c7, c8 = st.columns(4)

    c5.metric(
        "Compression High",
        fmt_price_for_display(
            selected_trade.compression_high
        ),
    )

    c6.metric(
        "Compression Low",
        fmt_price_for_display(
            selected_trade.compression_low
        ),
    )

    c7.metric(
        "Breakout",
        fmt_price_for_display(
            selected_trade.breakout_price
        ),
    )

    c8.metric(
        "Entry Ready",
        fmt_price_for_display(
            selected_trade.entry_ready_price
        ),
    )

    candles_df = inspection.candles

    if candles_df.empty:
        st.warning(
            f"No se pudieron cargar las velas "
            f"{inspector_timeframe} para este trade."
        )
        return

    inspector_fig = build_trade_inspector_chart(
        inspection=inspection,
        interval_minutes=interval_minutes,
        timeframe=inspector_timeframe,
    )

    st.plotly_chart(
        inspector_fig,
        use_container_width=True,
        key=f"{key_prefix}_chart",
        config={
            "displaylogo": False,
            "scrollZoom": True,
        },
    )
    
    render_compression_watch_history(
        selected_trade=selected_trade,
        key_prefix=f"{key_prefix}_watch_history",
    )

    with st.expander(
        f"{inspector_timeframe} candles",
        expanded=False,
    ):
        candle_columns = [
            "open_ts",
            "open",
            "high",
            "low",
            "close",
            "volume",
        ]

        available_candle_columns = [
            col
            for col in candle_columns
            if col in candles_df.columns
        ]

        st.dataframe(
            candles_df[available_candle_columns],
            use_container_width=True,
            hide_index=True,
        )
        
# ==========================================
# TP / SL REPLAY SEGMENT HELPERS
# ==========================================

def build_replay_trade_keys(data):
    """
    Construye una clave estable compartida entre:

    - trades.csv
    - post_trade_replay.csv
    - tp_sl_scenarios.csv
    - partial_tp_scenarios.csv

    La identidad utilizada es:
        SYMBOL + entry_ts UTC en milisegundos
    """
    if data is None or data.empty:
        return pd.Series(
            dtype="string",
            index=getattr(data, "index", None),
        )

    if "symbol" not in data.columns:
        return pd.Series(
            pd.NA,
            index=data.index,
            dtype="string",
        )

    entry_column = None

    if "entry_ts" in data.columns:
        entry_column = "entry_ts"

    elif "entry_ts_dt" in data.columns:
        entry_column = "entry_ts_dt"

    if entry_column is None:
        return pd.Series(
            pd.NA,
            index=data.index,
            dtype="string",
        )

    raw_entry_ts = data[entry_column]

    # Primero intentamos interpretar timestamps de texto o datetime.
    entry_datetime = pd.to_datetime(
        raw_entry_ts,
        utc=True,
        errors="coerce",
    )

    # Los timestamps numéricos necesitan una unidad explícita.
    numeric_entry_ts = pd.to_numeric(
        raw_entry_ts,
        errors="coerce",
    )

    numeric_mask = numeric_entry_ts.notna()

    if numeric_mask.any():
        numeric_values = numeric_entry_ts.loc[
            numeric_mask
        ].abs()

        seconds_mask = numeric_values < 1e11

        milliseconds_mask = (
            (numeric_values >= 1e11)
            & (numeric_values < 1e14)
        )

        microseconds_mask = (
            (numeric_values >= 1e14)
            & (numeric_values < 1e17)
        )

        nanoseconds_mask = numeric_values >= 1e17

        for unit, unit_mask in [
            ("s", seconds_mask),
            ("ms", milliseconds_mask),
            ("us", microseconds_mask),
            ("ns", nanoseconds_mask),
        ]:
            matching_indexes = unit_mask[
                unit_mask
            ].index

            if len(matching_indexes) == 0:
                continue

            entry_datetime.loc[
                matching_indexes
            ] = pd.to_datetime(
                numeric_entry_ts.loc[
                    matching_indexes
                ],
                unit=unit,
                utc=True,
                errors="coerce",
            )

    symbol = (
        data["symbol"]
        .fillna("")
        .astype(str)
        .str.strip()
        .str.upper()
    )

    # Pasamos todo a epoch milliseconds para que un mismo
    # timestamp tenga la misma representación en todos los CSV.
    entry_epoch_ms = pd.Series(
        pd.NA,
        index=data.index,
        dtype="Int64",
    )

    valid_datetime_mask = entry_datetime.notna()

    if valid_datetime_mask.any():
        entry_epoch_ms.loc[
            valid_datetime_mask
        ] = (
            entry_datetime.loc[
                valid_datetime_mask
            ]
            .astype("int64")
            // 1_000_000
        ).astype("Int64")

    trade_keys = (
        symbol
        + "|"
        + entry_epoch_ms.astype("string")
    )

    valid_key_mask = (
        symbol.ne("")
        & entry_epoch_ms.notna()
    )

    return trade_keys.where(
        valid_key_mask,
        pd.NA,
    )


def save_tp_sl_replay_segment(
    trades_df,
    source,
    description,
    selected_filters=None,
    bucket_definition=None,
):
    """
    Guarda un conjunto de trades únicos para utilizarlo
    posteriormente dentro de TP / SL Replay.
    """
    if trades_df is None or trades_df.empty:
        return {
            "saved": False,
            "reason": "No trades were selected.",
        }

    segment_df = trades_df.copy()

    segment_df["replay_trade_key"] = (
        build_replay_trade_keys(segment_df)
    )

    valid_trade_keys = (
        segment_df["replay_trade_key"]
        .dropna()
        .astype(str)
        .drop_duplicates()
        .tolist()
    )

    if not valid_trade_keys:
        return {
            "saved": False,
            "reason": (
                "The selected trades do not contain valid "
                "symbol and entry timestamp values."
            ),
        }

    st.session_state["tp_sl_replay_segment"] = {
        "source": str(source),
        "description": str(description),
        "selected_filters": selected_filters or [],
        "bucket_definition": bucket_definition,
        "trade_keys": valid_trade_keys,
        "trade_count": len(valid_trade_keys),
    }

    return {
        "saved": True,
        "trade_count": len(valid_trade_keys),
    }


def build_replay_bucket_definition(
    first_bucket_col,
    second_bucket_col,
    selected_keys,
):
    selected_pairs = []

    for selected_key in sorted(selected_keys):
        first_value, separator, second_value = (
            str(selected_key).partition(" || ")
        )

        if not separator:
            continue

        selected_pairs.append({
            "first_value": first_value,
            "second_value": second_value,
        })

    return {
        "first_bucket_col": str(first_bucket_col),
        "second_bucket_col": str(second_bucket_col),
        "selected_pairs": selected_pairs,
    }


def filter_by_replay_bucket_definition(
    data,
    bucket_definition,
):
    if data is None or data.empty or not bucket_definition:
        return pd.DataFrame()

    first_col = bucket_definition.get(
        "first_bucket_col"
    )
    second_col = bucket_definition.get(
        "second_bucket_col"
    )
    selected_pairs = bucket_definition.get(
        "selected_pairs",
        [],
    )

    if (
        not first_col
        or not second_col
        or first_col not in data.columns
        or second_col not in data.columns
        or not selected_pairs
    ):
        return pd.DataFrame()

    selected_pair_keys = {
        (
            str(pair.get("first_value")),
            str(pair.get("second_value")),
        )
        for pair in selected_pairs
    }

    first_values = data[first_col].astype(str)
    second_values = data[second_col].astype(str)

    match_mask = pd.Series(
        list(zip(first_values, second_values)),
        index=data.index,
    ).isin(selected_pair_keys)

    return data[match_mask].copy()


def load_tp_sl_replay_candidates():
    if not TP_SL_REPLAY_CANDIDATES_FILE.exists():
        return []

    try:
        with TP_SL_REPLAY_CANDIDATES_FILE.open(
            "r",
            encoding="utf-8",
        ) as candidate_file:
            payload = json.load(candidate_file)

        candidates = payload.get("candidates", [])

        return (
            candidates
            if isinstance(candidates, list)
            else []
        )

    except Exception:
        return []


def save_tp_sl_replay_candidates(candidates):
    TP_SL_REPLAY_CANDIDATES_FILE.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    temporary_path = (
        TP_SL_REPLAY_CANDIDATES_FILE
        .with_suffix(".json.tmp")
    )

    payload = {
        "version": 1,
        "candidates": candidates,
    }

    with temporary_path.open(
        "w",
        encoding="utf-8",
    ) as candidate_file:
        json.dump(
            payload,
            candidate_file,
            ensure_ascii=False,
            indent=2,
        )

    temporary_path.replace(
        TP_SL_REPLAY_CANDIDATES_FILE
    )


def candidate_checkpoint_status(forward_trades):
    if forward_trades < 10:
        return "Collecting data", 10
    if forward_trades < 20:
        return "First reading available", 20
    if forward_trades < 30:
        return "Preliminary validation", 30
    if forward_trades < 50:
        return "Growing validation sample", 50
    return "Forward sample established", None

def render_bucket_robustness_explorer(
    source_df,
    summary_df,
    first_bucket_col,
    second_bucket_col,
    first_bucket_label,
    second_bucket_label,
    key_prefix,
):
    st.markdown("#### 🔎 Analyze selected buckets")

    if source_df.empty or summary_df.empty:
        st.info("No bucket combinations available.")
        return

    required = [
        "symbol",
        "pnl",
        first_bucket_col,
        second_bucket_col,
    ]

    missing = [
        col for col in required
        if col not in source_df.columns
    ]

    if missing:
        st.info(f"Missing explorer columns: {missing}")
        return

    options_df = summary_df.copy()

    options_df = options_df[
        options_df["trades"] > 0
    ].copy()

    options_df["first_bucket_value"] = (
        options_df[first_bucket_col].astype(str)
    )

    options_df["second_bucket_value"] = (
        options_df[second_bucket_col].astype(str)
    )

    options_df["bucket_key"] = (
        options_df["first_bucket_value"]
        + " || "
        + options_df["second_bucket_value"]
    )

    options_df["bucket_label"] = (
        options_df["first_bucket_value"]
        + " × "
        + options_df["second_bucket_value"]
        + " — "
        + options_df["trades"].astype(int).astype(str)
        + " trades"
        + " | WR "
        + options_df["winrate"].round(2).astype(str)
        + "%"
        + " | PF "
        + options_df["pf"].fillna(0).round(2).astype(str)
    )

    options_df = options_df.sort_values(
        ["pf", "total_pnl"],
        ascending=False,
        na_position="last",
    )

    label_to_key = dict(zip(
        options_df["bucket_label"],
        options_df["bucket_key"],
    ))

    selected_labels = st.multiselect(
        "Select one or more bucket combinations",
        options=options_df["bucket_label"].tolist(),
        key=f"{key_prefix}_selected_buckets",
    )

    if not selected_labels:
        st.caption(
            "Select one or more rows to inspect their trades together."
        )
        return

    selected_keys = {
        label_to_key[label]
        for label in selected_labels
    }

    work = source_df.copy()

    work["_first_bucket"] = (
        work[first_bucket_col].astype(str)
    )

    work["_second_bucket"] = (
        work[second_bucket_col].astype(str)
    )

    work["_bucket_key"] = (
        work["_first_bucket"]
        + " || "
        + work["_second_bucket"]
    )

    selected_rows = work[
        work["_bucket_key"].isin(selected_keys)
    ].copy()

    selected_rows["pnl"] = pd.to_numeric(
        selected_rows["pnl"],
        errors="coerce",
    )

    selected_rows = selected_rows.dropna(subset=["pnl"])

    # ==========================================
    # TRADE KEY
    # ==========================================
    if "trade_id" in selected_rows.columns:
        selected_rows["trade_key"] = (
            selected_rows["trade_id"].astype(str)
        )

    elif "entry_ts" in selected_rows.columns:
        selected_rows["trade_key"] = (
            selected_rows["symbol"].astype(str)
            + "_"
            + selected_rows["entry_ts"].astype(str)
        )

    elif "entry_ts_dt" in selected_rows.columns:
        selected_rows["trade_key"] = (
            selected_rows["symbol"].astype(str)
            + "_"
            + selected_rows["entry_ts_dt"].astype(str)
        )

    else:
        selected_rows["trade_key"] = (
            selected_rows["symbol"].astype(str)
            + "_row_"
            + selected_rows.index.astype(str)
        )

    total_rows = len(selected_rows)
    unique_trades = selected_rows["trade_key"].nunique()
    duplicate_rows = selected_rows["trade_key"].duplicated().sum()

    # Los reportes estadísticos utilizan trades únicos.
    edge_df = selected_rows.drop_duplicates(
        subset=["trade_key"],
        keep="first",
    ).copy()

    edge_df["is_win"] = edge_df["pnl"] > 0

    # ==========================================
    # TIMESTAMP
    # ==========================================
    if "entry_ts_dt" in edge_df.columns:
        edge_df["entry_datetime"] = pd.to_datetime(
            edge_df["entry_ts_dt"],
            errors="coerce",
            utc=True,
        )

    elif "entry_ts" in edge_df.columns:
        numeric_entry_ts = pd.to_numeric(
            edge_df["entry_ts"],
            errors="coerce",
        )

        edge_df["entry_datetime"] = pd.to_datetime(
            numeric_entry_ts,
            unit="ms",
            errors="coerce",
            utc=True,
        )

        missing_datetime = edge_df["entry_datetime"].isna()

        if missing_datetime.any():
            edge_df.loc[
                missing_datetime,
                "entry_datetime",
            ] = pd.to_datetime(
                edge_df.loc[missing_datetime, "entry_ts"],
                errors="coerce",
                utc=True,
            )

    else:
        edge_df["entry_datetime"] = pd.NaT

    edge_df["entry_date"] = (
        edge_df["entry_datetime"].dt.date
    )

    edge_df["entry_30m"] = (
        edge_df["entry_datetime"].dt.floor("30min")
    )

    # ==========================================
    # SUMMARY HELPERS
    # ==========================================
    def edge_summary(data):
        if data.empty:
            return {
                "trades": 0,
                "wins": 0,
                "losses": 0,
                "winrate": 0.0,
                "total_pnl": 0.0,
                "avg_pnl": 0.0,
                "pf": None,
                "avg_mfe": None,
                "avg_mae": None,
            }

        pnl = pd.to_numeric(
            data["pnl"],
            errors="coerce",
        ).dropna()

        wins = int((pnl > 0).sum())
        losses = int((pnl <= 0).sum())
        
        avg_mfe = (
            pd.to_numeric(
                data["max_favorable_pct"],
                errors="coerce",
            ).mean()
            if "max_favorable_pct" in data.columns
            else None
        )

        avg_mae = (
            pd.to_numeric(
                data["max_adverse_pct"],
                errors="coerce",
            ).mean()
            if "max_adverse_pct" in data.columns
            else None
        )

        return {
            "trades": len(pnl),
            "wins": wins,
            "losses": losses,
            "winrate": (
                wins / len(pnl) * 100
                if len(pnl) > 0
                else 0
            ),
            "total_pnl": pnl.sum(),
            "avg_pnl": pnl.mean(),
            "pf": profit_factor(pnl),
            "avg_mfe": avg_mfe,
            "avg_mae": avg_mae,
        }

    def render_summary_metrics(data):
        result = edge_summary(data)

        c1, c2, c3, c4 = st.columns(4)

        c1.metric("Trades", result["trades"])
        c2.metric("Winrate", f'{result["winrate"]:.2f}%')
        c3.metric("Total PnL", f'{result["total_pnl"]:.4f}')
        c4.metric(
            "Profit Factor",
            (
                f'{result["pf"]:.2f}'
                if result["pf"] is not None
                else "∞"
            ),
        )
        
        c5, c6 = st.columns(2)

        c5.metric(
            "Avg MFE",
            (
                f'{result["avg_mfe"]:.4f}%'
                if pd.notna(result["avg_mfe"])
                else "N/A"
            ),
        )

        c6.metric(
            "Avg MAE",
            (
                f'{result["avg_mae"]:.4f}%'
                if pd.notna(result["avg_mae"])
                else "N/A"
            ),
        )

    def build_group_report(data, group_col):
        valid = data.dropna(subset=[group_col]).copy()

        if valid.empty:
            return pd.DataFrame()

        report = (
            valid
            .groupby(group_col, dropna=False)
            .agg(
                trades=("trade_key", "nunique"),
                wins=("pnl", lambda x: int((x > 0).sum())),
                losses=("pnl", lambda x: int((x <= 0).sum())),
                winrate=(
                    "pnl",
                    lambda x: round((x > 0).mean() * 100, 2),
                ),
                avg_pnl=("pnl", "mean"),
                total_pnl=("pnl", "sum"),
                avg_mfe=("max_favorable_pct", "mean"),
                avg_mae=("max_adverse_pct", "mean"),
                pf=("pnl", profit_factor),
            )
            .reset_index()
        )

        report["trade_share_pct"] = (
            report["trades"]
            / edge_df["trade_key"].nunique()
            * 100
        ).round(2)

        for col in [
            "avg_pnl",
            "total_pnl",
            "avg_mfe",
            "avg_mae",
        ]:
            report[col] = report[col].round(4)

        return report.sort_values(
            ["trades", "total_pnl"],
            ascending=False,
        )

    # ==========================================
    # MAIN METRICS
    # ==========================================
    st.markdown(
        f"##### Selected edge: "
        f"{first_bucket_label} × {second_bucket_label}"
    )

    u1, u2, u3 = st.columns(3)

    u1.metric("Selected rows", total_rows)
    u2.metric("Unique trades", unique_trades)
    u3.metric("Duplicate rows", int(duplicate_rows))

    render_summary_metrics(edge_df)
    
    replay_segment_description = (
        f"{first_bucket_label} × "
        f"{second_bucket_label}"
    )

    replay_bucket_definition = (
        build_replay_bucket_definition(
            first_bucket_col=first_bucket_col,
            second_bucket_col=second_bucket_col,
            selected_keys=selected_keys,
        )
    )

    if st.button(
        "🧪 Send selected trades to TP / SL Replay",
        key=f"{key_prefix}_send_to_tp_sl_replay",
        type="primary",
        use_container_width=True,
    ):
        save_result = save_tp_sl_replay_segment(
            trades_df=edge_df,
            source="Bucket Robustness Explorer",
            description=replay_segment_description,
            selected_filters=selected_labels,
            bucket_definition=replay_bucket_definition,
        )

        if save_result["saved"]:
            st.success(
                f"{save_result['trade_count']} unique trades "
                "were sent to TP / SL Replay."
            )
        else:
            st.error(
                save_result["reason"]
            )

    if duplicate_rows > 0:
        st.warning(
            "Duplicate rows were excluded from all statistical reports."
        )
    else:
        st.success(
            "All selected rows correspond to unique trades."
        )

    (
        trades_tab,
        deep_dive_tab,
        days_tab,
        symbols_tab,
        batches_tab,
        btc_tab,
        robustness_tab,
    ) = st.tabs([
        "All Trades",
        "Structure & Risk",
        "By Day",
        "By Symbol",
        "30m Batches",
        "BTC Context",
        "Robustness",
    ])

    # ==========================================
    # ALL TRADES
    # ==========================================
    with trades_tab:
        # Ordenar los trades seleccionados.
        trade_detail_df = edge_df.sort_values(
            (
                "entry_datetime"
                if (
                    "entry_datetime" in edge_df.columns
                    and edge_df["entry_datetime"].notna().any()
                )
                else "pnl"
            ),
            ascending=False,
        )

        # Mantiene todas las features con sus tipos originales
        # para el Trade Inspector.
        inspector_source_df = (
            trade_detail_df
            .reset_index(drop=True)
            .copy()
        )

        # La tabla visible parte del dataframe completo.
        trade_display_df = inspector_source_df.copy()

        # Ocultar solamente columnas auxiliares creadas internamente
        # por Analyze selected buckets.
        internal_helper_cols = [
            "_first_bucket",
            "_second_bucket",
            "_bucket_key",
            "is_win",
            "entry_datetime",
            "entry_date",
            "entry_30m",
        ]

        trade_display_df = trade_display_df.drop(
            columns=[
                col
                for col in internal_helper_cols
                if col in trade_display_df.columns
            ],
            errors="ignore",
        )

        # Formatear timestamps solamente para visualización.
        timestamp_pairs = [
            ("compression_created_ts", "compression_created_ts_dt"),
            ("signal_ts", "signal_ts_dt"),
            ("breakout_ts", "breakout_ts_dt"),
            ("entry_ready_ts", "entry_ready_ts_dt"),
            ("entry_ts", "entry_ts_dt"),
            ("exit_ts", "exit_ts_dt"),
        ]

        datetime_helper_cols = []

        for raw_col, dt_col in timestamp_pairs:
            if dt_col not in trade_display_df.columns:
                continue

            parsed_ts = pd.to_datetime(
                trade_display_df[dt_col],
                errors="coerce",
                utc=True,
            )

            if raw_col in trade_display_df.columns:
                trade_display_df[raw_col] = parsed_ts.dt.strftime(
                    "%d-%m-%Y %H:%M"
                )
            else:
                trade_display_df[dt_col] = parsed_ts.dt.strftime(
                    "%d-%m-%Y %H:%M"
                )

            if (
                raw_col in trade_display_df.columns
                and dt_col != raw_col
            ):
                datetime_helper_cols.append(dt_col)

        trade_display_df = trade_display_df.drop(
            columns=datetime_helper_cols,
            errors="ignore",
        )

        # Mover primero las columnas más importantes.
        leading_cols = [
            "trade_key",
            "symbol",
            "side",
            "leverage",
            "signal_ts",
            "entry_ts",
            "exit_ts",
            "real_entry",
            "real_exit",
            "pnl",
            "pnl_usd",
            "fees",
            "exit_reason",
            first_bucket_col,
            second_bucket_col,
        ]

        leading_cols = [
            col
            for col in dict.fromkeys(leading_cols)
            if col in trade_display_df.columns
        ]

        remaining_cols = [
            col
            for col in trade_display_df.columns
            if col not in leading_cols
        ]

        trade_display_df = trade_display_df[
            leading_cols + remaining_cols
        ]

        st.caption(
            "Seleccioná un trade para inspeccionar "
            "gráficamente su compresión."
        )

        bucket_trades_event = st.dataframe(
            trade_display_df,
            use_container_width=True,
            hide_index=True,
            key=f"{key_prefix}_trade_selector",
            on_select="rerun",
            selection_mode="single-row",
        )

        selected_trade_rows = (
            bucket_trades_event.selection.rows
        )

        if selected_trade_rows:
            selected_position = selected_trade_rows[0]

            selected_trade_row = (
                inspector_source_df.iloc[
                    selected_position
                ]
            )

            render_trade_inspector_for_row(
                row=selected_trade_row,
                status="CLOSED",
                key_prefix=(
                    f"{key_prefix}_"
                    f"{selected_trade_row['trade_key']}"
                ),
            )
        
    # ==========================================
    # STRUCTURE AND RISK DEEP DIVE
    # ==========================================
    with deep_dive_tab:
        st.markdown(
            "##### Structure and risk inside selected buckets"
        )

        st.caption(
            "Analiza solamente los trades pertenecientes a las "
            "combinaciones seleccionadas en Breakout Extension % "
            "× Entry vs Breakout %. MFE y MAE son métricas "
            "posteriores al trade y se usan solo como diagnóstico."
        )

        deep_dive_dimensions = {
            "Entry vs Compression High":
                "entry_vs_compression_bucket",

            "Compression Height":
                "compression_height_bucket",

            "Structural Risk":
                "structural_risk_detail_bucket",

            "Compression Duration":
                "compression_duration_bucket",

            "Compression Shape":
                "compression_shape",
        }

        available_deep_dive_dimensions = {
            label: column
            for label, column
            in deep_dive_dimensions.items()
            if (
                column in edge_df.columns
                and edge_df[column].notna().any()
            )
        }

        if not available_deep_dive_dimensions:
            st.info(
                "No structure or risk dimensions are available "
                "for the selected trades."
            )

        else:
            dd1, dd2 = st.columns([2, 1])

            deep_dive_labels = list(
                available_deep_dive_dimensions.keys()
            )

            default_deep_dive_label = (
                "Entry vs Compression High"
                if "Entry vs Compression High"
                in deep_dive_labels
                else deep_dive_labels[0]
            )

            with dd1:
                selected_deep_dive_label = st.selectbox(
                    "Deep-dive dimension",
                    options=deep_dive_labels,
                    index=deep_dive_labels.index(
                        default_deep_dive_label
                    ),
                    key=f"{key_prefix}_deep_dive_dimension",
                )

            with dd2:
                deep_dive_min_trades = st.number_input(
                    "Minimum trades",
                    min_value=1,
                    max_value=max(1, len(edge_df)),
                    value=min(3, max(1, len(edge_df))),
                    step=1,
                    key=f"{key_prefix}_deep_dive_min_trades",
                )

            selected_deep_dive_col = (
                available_deep_dive_dimensions[
                    selected_deep_dive_label
                ]
            )

            deep_dive_report = build_group_report(
                edge_df,
                selected_deep_dive_col,
            )

            if not deep_dive_report.empty:
                deep_dive_report = deep_dive_report[
                    deep_dive_report["trades"]
                    >= int(deep_dive_min_trades)
                ].copy()

            if deep_dive_report.empty:
                st.info(
                    "No groups meet the selected minimum "
                    "trade requirement."
                )

            else:
                st.dataframe(
                    deep_dive_report,
                    use_container_width=True,
                    hide_index=True,
                    key=f"{key_prefix}_deep_dive_report",
                )

                st.caption(
                    "trade_share_pct muestra qué porcentaje de "
                    "los trades seleccionados pertenece a cada grupo."
                )

    # ==========================================
    # BY DAY
    # ==========================================
    with days_tab:
        day_report = build_group_report(
            edge_df,
            "entry_date",
        )

        if day_report.empty:
            st.info("No valid entry dates available.")

        else:
            d1, d2 = st.columns(2)

            d1.metric(
                "Unique Days",
                day_report["entry_date"].nunique(),
            )
            d2.metric(
                "Largest Day Share",
                f'{day_report["trade_share_pct"].max():.2f}%',
            )

            st.dataframe(
                day_report,
                use_container_width=True,
                hide_index=True,
            )

    # ==========================================
    # BY SYMBOL
    # ==========================================
    with symbols_tab:
        symbol_report = build_group_report(
            edge_df,
            "symbol",
        )

        if symbol_report.empty:
            st.info("No symbols available.")

        else:
            s1, s2 = st.columns(2)

            s1.metric(
                "Unique Symbols",
                edge_df["symbol"].nunique(),
            )
            s2.metric(
                "Largest Symbol Share",
                f'{symbol_report["trade_share_pct"].max():.2f}%',
            )

            st.dataframe(
                symbol_report,
                use_container_width=True,
                hide_index=True,
            )

    # ==========================================
    # 30M BATCHES
    # ==========================================
    with batches_tab:
        valid_batches = edge_df.dropna(
            subset=["entry_30m"]
        )

        if valid_batches.empty:
            st.info("No valid entry timestamps available.")

        else:
            batch_report = (
                valid_batches
                .groupby("entry_30m")
                .agg(
                    trades=("trade_key", "nunique"),
                    symbols=(
                        "symbol",
                        lambda x: ", ".join(
                            sorted(set(x.astype(str)))
                        ),
                    ),
                    wins=("pnl", lambda x: int((x > 0).sum())),
                    losses=("pnl", lambda x: int((x <= 0).sum())),
                    total_pnl=("pnl", "sum"),
                    pf=("pnl", profit_factor),
                )
                .reset_index()
                .sort_values(
                    ["trades", "total_pnl"],
                    ascending=False,
                )
            )

            batch_report["trade_share_pct"] = (
                batch_report["trades"]
                / unique_trades
                * 100
            ).round(2)

            batch_report["total_pnl"] = (
                batch_report["total_pnl"].round(4)
            )

            b1, b2 = st.columns(2)

            b1.metric(
                "Unique 30m Batches",
                len(batch_report),
            )
            b2.metric(
                "Largest Batch",
                int(batch_report["trades"].max()),
            )

            st.dataframe(
                batch_report,
                use_container_width=True,
                hide_index=True,
            )

    # ==========================================
    # BTC CONTEXT
    # ==========================================
    with btc_tab:
        btc_context_cols = []

        for col in edge_df.columns:
            if "btc" not in col.lower():
                continue

            unique_values = edge_df[col].nunique(
                dropna=True
            )

            if 1 < unique_values <= 30:
                btc_context_cols.append(col)

        if not btc_context_cols:
            st.info(
                "No categorical BTC context columns available."
            )

        else:
            selected_btc_cols = st.multiselect(
                "BTC context dimensions",
                options=btc_context_cols,
                default=btc_context_cols[:3],
                key=f"{key_prefix}_btc_dimensions",
            )

            if not selected_btc_cols:
                st.caption(
                    "Select at least one BTC context dimension."
                )

            for btc_col in selected_btc_cols:
                st.markdown(f"##### {btc_col}")

                btc_report = build_group_report(
                    edge_df,
                    btc_col,
                )

                st.dataframe(
                    btc_report,
                    use_container_width=True,
                    hide_index=True,
                )

    # ==========================================
    # ROBUSTNESS TEST
    # ==========================================
    with robustness_tab:
        robustness_rows = []

        baseline = edge_summary(edge_df)

        robustness_rows.append({
            "scenario": "Original selected buckets",
            **baseline,
        })

        # Remove the day producing the most PnL.
        valid_days = edge_df.dropna(
            subset=["entry_date"]
        )

        if not valid_days.empty:
            pnl_by_day = valid_days.groupby(
                "entry_date"
            )["pnl"].sum()

            best_day = pnl_by_day.idxmax()

            without_best_day = edge_df[
                edge_df["entry_date"] != best_day
            ]

            robustness_rows.append({
                "scenario": f"Without best day: {best_day}",
                **edge_summary(without_best_day),
            })

        # Remove the symbol producing the most PnL.
        if "symbol" in edge_df.columns:
            pnl_by_symbol = edge_df.groupby(
                "symbol"
            )["pnl"].sum()

            if not pnl_by_symbol.empty:
                best_symbol = pnl_by_symbol.idxmax()

                without_best_symbol = edge_df[
                    edge_df["symbol"] != best_symbol
                ]

                robustness_rows.append({
                    "scenario": (
                        f"Without best symbol: {best_symbol}"
                    ),
                    **edge_summary(without_best_symbol),
                })

        # Remove batch containing the most trades.
        valid_batches = edge_df.dropna(
            subset=["entry_30m"]
        )

        if not valid_batches.empty:
            batch_sizes = valid_batches.groupby(
                "entry_30m"
            )["trade_key"].nunique()

            largest_batch = batch_sizes.idxmax()

            without_largest_batch = edge_df[
                edge_df["entry_30m"] != largest_batch
            ]

            robustness_rows.append({
                "scenario": (
                    f"Without largest batch: {largest_batch}"
                ),
                **edge_summary(without_largest_batch),
            })

        robustness_df = pd.DataFrame(
            robustness_rows
        )

        for col in [
            "winrate",
            "total_pnl",
            "avg_pnl",
            "pf",
        ]:
            if col in robustness_df.columns:
                robustness_df[col] = pd.to_numeric(
                    robustness_df[col],
                    errors="coerce",
                ).round(4)

        st.dataframe(
            robustness_df,
            use_container_width=True,
            hide_index=True,
        )

        if len(robustness_df) > 1:
            positive_after_tests = (
                robustness_df.iloc[1:]["total_pnl"] > 0
            ).all()

            pf_after_tests = (
                robustness_df.iloc[1:]["pf"]
                .fillna(999)
                > 1
            ).all()

            if positive_after_tests and pf_after_tests:
                st.success(
                    "The selected edge remains positive after all "
                    "concentration tests."
                )
            else:
                st.warning(
                    "The selected edge weakens after removing one "
                    "of its main concentration sources."
                )

def load_compression_snapshots(base_dir="compression_snapshots"):
    base_path = Path(base_dir)

    rows = []

    if not base_path.exists():
        return pd.DataFrame()

    for path in base_path.glob("*.json"):
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)

            rows.append(data)

        except Exception:
            continue

    return pd.DataFrame(rows)

def load_compression_pipeline(path="compression_pipeline.json"):
    path = Path(path)

    if not path.exists():
        return pd.DataFrame()

    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)

        return pd.DataFrame(data)

    except Exception:
        return pd.DataFrame()

def filter_by_window(df, days=None, yesterday=False):
    if df.empty or "entry_ts_dt" not in df.columns:
        return pd.DataFrame()

    now = pd.Timestamp.now(tz=TZ)

    if yesterday:
        target = (now - pd.Timedelta(days=1)).date()

        return df[
            df["entry_ts_dt"].dt.date == target
        ]

    if days == 0:
        return df[
            df["entry_ts_dt"].dt.date == now.date()
        ]

    if days is None:
        return df

    start = (now - pd.Timedelta(days=days)).date()

    return df[
        df["entry_ts_dt"].dt.date >= start
    ]

def safe_sum(df, col):
    if col not in df.columns or df.empty:
        return 0.0
    return round(pd.to_numeric(df[col], errors="coerce").fillna(0).sum(), 2)


def safe_mean(df, col):
    if col not in df.columns or df.empty:
        return 0.0
    series = pd.to_numeric(df[col], errors="coerce").dropna()
    if series.empty:
        return 0.0
    return round(series.mean(), 2)


def safe_max(df, col):
    if col not in df.columns or df.empty:
        return 0.0
    series = pd.to_numeric(df[col], errors="coerce").dropna()
    if series.empty:
        return 0.0
    return round(series.max(), 2)

def profit_factor(x):
    wins = x[x > 0].sum()
    losses = abs(x[x < 0].sum())
    return round(wins / losses, 2) if losses > 0 else None

def build_state_machine_timing_report(
    trades_df,
    entry_ready_events_df,
    candle_minutes=1,
):
    if trades_df is None or trades_df.empty:
        return pd.DataFrame(), pd.DataFrame()

    if (
        entry_ready_events_df is None
        or entry_ready_events_df.empty
    ):
        return pd.DataFrame(), pd.DataFrame()

    required_trade_cols = [
        "symbol",
        "pnl",
        "breakout_ts",
        "compression_created_ts",
    ]

    missing_cols = [
        col
        for col in required_trade_cols
        if col not in trades_df.columns
    ]

    if missing_cols:
        return pd.DataFrame(), pd.DataFrame()

    work = trades_df.copy()
    ready_events = entry_ready_events_df.copy()

    # ==========================================
    # NORMALIZE JOIN KEYS
    # ==========================================

    work["symbol"] = (
        work["symbol"]
        .fillna("")
        .astype(str)
        .str.upper()
        .str.strip()
    )

    ready_events["symbol"] = (
        ready_events["symbol"]
        .fillna("")
        .astype(str)
        .str.upper()
        .str.strip()
    )

    work["compression_created_ts"] = pd.to_numeric(
        work["compression_created_ts"],
        errors="coerce",
    )

    ready_events["compression_created_ts"] = pd.to_numeric(
        ready_events["compression_created_ts"],
        errors="coerce",
    )

    # ==========================================
    # JOIN TRADE ↔ WATCH JOURNAL
    # ==========================================

    work = work.merge(
        ready_events,
        on=[
            "symbol",
            "compression_created_ts",
        ],
        how="left",
        validate="many_to_one",
    )

    # ==========================================
    # NORMALIZE TIMESTAMPS
    # ==========================================

    def normalize_timestamp_series(series):
        numeric = pd.to_numeric(
            series,
            errors="coerce",
        )

        result = pd.Series(
            pd.NaT,
            index=series.index,
            dtype="datetime64[ns, UTC]",
        )

        milliseconds_mask = (
            numeric.notna()
            & numeric.abs().ge(100_000_000_000)
        )

        seconds_mask = (
            numeric.notna()
            & ~milliseconds_mask
        )

        text_mask = numeric.isna()

        if milliseconds_mask.any():
            result.loc[milliseconds_mask] = pd.to_datetime(
                numeric.loc[milliseconds_mask],
                unit="ms",
                errors="coerce",
                utc=True,
            )

        if seconds_mask.any():
            result.loc[seconds_mask] = pd.to_datetime(
                numeric.loc[seconds_mask],
                unit="s",
                errors="coerce",
                utc=True,
            )

        if text_mask.any():
            result.loc[text_mask] = pd.to_datetime(
                series.loc[text_mask],
                errors="coerce",
                utc=True,
            )

        return result

    work["breakout_ts_dt"] = normalize_timestamp_series(
        work["breakout_ts"]
    )

    work["entry_ready_ts_dt"] = normalize_timestamp_series(
        work["journal_entry_ready_ts"]
    )

    work["pnl"] = pd.to_numeric(
        work["pnl"],
        errors="coerce",
    )

    work = work.dropna(
        subset=[
            "pnl",
            "breakout_ts_dt",
            "entry_ready_ts_dt",
        ]
    ).copy()

    if work.empty:
        return pd.DataFrame(), work

    # ==========================================
    # BREAKOUT -> ENTRY READY
    # ==========================================

    work["breakout_to_ready_minutes"] = (
        (
            work["entry_ready_ts_dt"]
            - work["breakout_ts_dt"]
        )
        .dt.total_seconds()
        .div(60)
    )

    work["breakout_to_ready_bars"] = (
        work["breakout_to_ready_minutes"]
        / float(candle_minutes)
    ).round()

    work["breakout_to_ready_bars"] = pd.to_numeric(
        work["breakout_to_ready_bars"],
        errors="coerce",
    ).astype("Int64")

    work = work[
        work["breakout_to_ready_bars"] >= 0
    ].copy()

    # ==========================================
    # BUCKET
    # ==========================================

    def timing_bucket(bars):
        if pd.isna(bars):
            return "Unknown"

        bars = int(bars)

        if bars == 0:
            return "0 bars — same breakout candle"

        if bars == 1:
            return "1 bar"

        if bars == 2:
            return "2 bars"

        if bars == 3:
            return "3 bars"

        if bars <= 5:
            return "4–5 bars"

        return ">5 bars"

    work["breakout_to_ready_bucket"] = (
        work["breakout_to_ready_bars"]
        .apply(timing_bucket)
    )

    bucket_order = [
        "0 bars — same breakout candle",
        "1 bar",
        "2 bars",
        "3 bars",
        "4–5 bars",
        ">5 bars",
    ]

    work["breakout_to_ready_bucket"] = pd.Categorical(
        work["breakout_to_ready_bucket"],
        categories=bucket_order,
        ordered=True,
    )

    # ==========================================
    # PERFORMANCE REPORT
    # ==========================================

    report = (
        work
        .groupby(
            "breakout_to_ready_bucket",
            observed=True,
        )
        .agg(
            trades=("pnl", "count"),

            wins=(
                "pnl",
                lambda x: int((x > 0).sum()),
            ),

            losses=(
                "pnl",
                lambda x: int((x <= 0).sum()),
            ),

            winrate=(
                "pnl",
                lambda x: round(
                    (x > 0).mean() * 100,
                    2,
                ),
            ),

            avg_pnl=("pnl", "mean"),

            total_pnl=("pnl", "sum"),

            profit_factor=(
                "pnl",
                profit_factor,
            ),

            avg_breakout_to_ready_min=(
                "breakout_to_ready_minutes",
                "mean",
            ),
        )
        .reset_index()
    )

    report["avg_pnl"] = report["avg_pnl"].round(4)
    report["total_pnl"] = report["total_pnl"].round(4)

    report["avg_breakout_to_ready_min"] = (
        report["avg_breakout_to_ready_min"]
        .round(2)
    )

    return report, work

def build_state_machine_funnel(
    watch_events_df,
):
    if (
        watch_events_df is None
        or watch_events_df.empty
    ):
        return pd.DataFrame(), pd.DataFrame()

    work = watch_events_df.copy()

    required_cols = [
        "symbol",
        "compression_created_ts",
        "event",
        "state",
        "breakout_detected",
        "entry_ready",
    ]

    missing_cols = [
        col
        for col in required_cols
        if col not in work.columns
    ]

    if missing_cols:
        return pd.DataFrame(), pd.DataFrame()

    # ==========================================
    # NORMALIZE BOOLEAN VALUES
    # ==========================================

    def to_bool(value):
        if value is True:
            return True

        if value is False:
            return False

        if pd.isna(value):
            return False

        return str(value).strip().lower() in {
            "true",
            "1",
            "yes",
        }

    work["_breakout"] = (
        work["breakout_detected"]
        .apply(to_bool)
    )

    work["_entry_ready"] = (
        work["entry_ready"]
        .apply(to_bool)
    )

    work["_event"] = (
        work["event"]
        .fillna("")
        .astype(str)
        .str.upper()
    )

    work["_state"] = (
        work["state"]
        .fillna("")
        .astype(str)
        .str.upper()
    )

    # ==========================================
    # ONE ROW PER WATCH
    # ==========================================

    watch_rows = []

    grouped = work.groupby(
        [
            "symbol",
            "compression_created_ts",
        ],
        dropna=False,
    )

    for (
        symbol,
        compression_created_ts,
    ), group in grouped:

        events = set(group["_event"])
        states = set(group["_state"])

        breakout_reached = bool(
            group["_breakout"].any()
            or group["breakout_ts"].notna().any()
            or "BREAKOUT_DETECTED" in events
            or "BREAKOUT_DETECTED" in states
            or "WAIT_PULLBACK" in events
            or "WAIT_PULLBACK" in states
            or "ENTRY_READY" in events
            or "ENTRY_READY" in states
        )

        entry_ready_reached = bool(
            group["_entry_ready"].any()
            or "ENTRY_READY" in events
            or "ENTRY_READY" in states
        )

        expired = bool(
            "EXPIRED" in events
            or "EXPIRED" in states
        )

        if entry_ready_reached:
            outcome = "ENTRY_READY"

        elif expired and breakout_reached:
            outcome = "EXPIRED_AFTER_BREAKOUT"

        elif expired:
            outcome = "EXPIRED_NO_BREAKOUT"

        elif breakout_reached:
            outcome = "BREAKOUT_NO_TERMINAL_EVENT"

        else:
            outcome = "WATCH_NO_TERMINAL_EVENT"
            
        first_row = (
            group
            .sort_values(
                "event_ts",
                ascending=True,
                na_position="last",
            )
            .iloc[0]
        )

        watch_rows.append({
            "symbol": symbol,

            "compression_created_ts": (
                compression_created_ts
            ),

            "breakout_reached": (
                breakout_reached
            ),

            "entry_ready_reached": (
                entry_ready_reached
            ),

            "expired": expired,

            "outcome": outcome,

            # =========================
            # INITIAL WATCH FEATURES
            # =========================

            "compression_score": first_row.get(
                "compression_score"
            ),

            "trend_score": first_row.get(
                "trend_score"
            ),

            "range_ratio": first_row.get(
                "range_ratio"
            ),

            "atr_ratio": first_row.get(
                "atr_ratio"
            ),

            "volume_ratio": first_row.get(
                "volume_ratio"
            ),

            "avg_body_pct": first_row.get(
                "avg_body_pct"
            ),

            "compression_range_pct": first_row.get(
                "compression_range_pct"
            ),

            "compression_height_pct": first_row.get(
                "compression_height_pct"
            ),

            "compression_duration": first_row.get(
                "compression_duration"
            ),

            "inside_ratio": first_row.get(
                "inside_ratio"
            ),

            "touches_high": first_row.get(
                "touches_high"
            ),

            "touches_low": first_row.get(
                "touches_low"
            ),

            "touches_high_ratio": first_row.get(
                "touches_high_ratio"
            ),

            "touches_low_ratio": first_row.get(
                "touches_low_ratio"
            ),

            "touch_imbalance_ratio": first_row.get(
                "touch_imbalance_ratio"
            ),

            "upper_slope": first_row.get(
                "upper_slope"
            ),

            "lower_slope": first_row.get(
                "lower_slope"
            ),

            "slope_difference": first_row.get(
                "slope_difference"
            ),

            "compression_shape": first_row.get(
                "compression_shape"
            ),

            "compression_quality_label": first_row.get(
                "compression_quality_label"
            ),

            "selected_lookback": first_row.get(
                "selected_lookback"
            ),

            "selection_score": first_row.get(
                "selection_score"
            ),
        })

    watches = pd.DataFrame(watch_rows)

    if watches.empty:
        return pd.DataFrame(), watches

    # ==========================================
    # FUNNEL
    # ==========================================

    total_watches = len(watches)

    breakout_watches = int(
        watches["breakout_reached"].sum()
    )

    entry_ready_watches = int(
        watches["entry_ready_reached"].sum()
    )

    funnel = pd.DataFrame([
        {
            "stage": "WATCH_CREATED",
            "watches": total_watches,
        },
        {
            "stage": "BREAKOUT",
            "watches": breakout_watches,
        },
        {
            "stage": "ENTRY_READY",
            "watches": entry_ready_watches,
        },
    ])

    funnel["vs_initial_pct"] = (
        funnel["watches"]
        / total_watches
        * 100
    ).round(2)

    funnel["conversion_from_previous_pct"] = 100.0

    if total_watches > 0:
        funnel.loc[
            funnel["stage"] == "BREAKOUT",
            "conversion_from_previous_pct",
        ] = round(
            breakout_watches
            / total_watches
            * 100,
            2,
        )

    if breakout_watches > 0:
        funnel.loc[
            funnel["stage"] == "ENTRY_READY",
            "conversion_from_previous_pct",
        ] = round(
            entry_ready_watches
            / breakout_watches
            * 100,
            2,
        )

    return funnel, watches

def replay_profit_factor(values):
    values = pd.to_numeric(
        values,
        errors="coerce",
    ).dropna()

    gross_profit = values[values > 0].sum()
    gross_loss = abs(values[values < 0].sum())

    if gross_loss == 0:
        return None

    return gross_profit / gross_loss

def summarize_replay_strategy(
    strategy_name,
    pnl_values,
):
    """
    Resume económicamente una serie de resultados porcentuales.
    """

    pnl = pd.to_numeric(
        pd.Series(pnl_values),
        errors="coerce",
    )

    pnl = pnl.replace(
        [
            np.inf,
            -np.inf,
        ],
        np.nan,
    ).dropna()

    if pnl.empty:
        return {
            "strategy": strategy_name,
            "trades": 0,
            "wins": 0,
            "losses": 0,
            "breakeven": 0,
            "winrate": 0.0,
            "avg_win": np.nan,
            "avg_loss": np.nan,
            "payoff_ratio": np.nan,
            "breakeven_winrate": np.nan,
            "avg_pnl": np.nan,
            "total_pnl": 0.0,
            "profit_factor": np.nan,
            "max_drawdown": np.nan,
        }

    wins = pnl[pnl > 0]
    losses = pnl[pnl < 0]
    breakeven = pnl[pnl == 0]

    gross_profit = wins.sum()
    gross_loss = abs(
        losses.sum()
    )

    avg_win = (
        wins.mean()
        if not wins.empty
        else np.nan
    )

    avg_loss = (
        losses.mean()
        if not losses.empty
        else np.nan
    )

    if (
        pd.notna(avg_win)
        and pd.notna(avg_loss)
        and abs(avg_loss) > 0
    ):
        payoff_ratio = (
            avg_win / abs(avg_loss)
        )

        breakeven_winrate = (
            abs(avg_loss)
            / (
                avg_win
                + abs(avg_loss)
            )
            * 100
        )

    else:
        payoff_ratio = np.nan
        breakeven_winrate = np.nan

    if gross_loss > 0:
        profit_factor = (
            gross_profit / gross_loss
        )

    elif gross_profit > 0:
        profit_factor = np.inf

    else:
        profit_factor = np.nan

    # Incluye equity inicial en cero para calcular
    # correctamente un drawdown desde el primer trade.
    equity = pd.Series(
        np.concatenate([
            [0.0],
            pnl.to_numpy(),
        ])
    ).cumsum()

    running_max = equity.cummax()

    drawdown = (
        equity - running_max
    )

    max_drawdown = abs(
        drawdown.min()
    )

    return {
        "strategy": strategy_name,
        "trades": len(pnl),
        "wins": len(wins),
        "losses": len(losses),
        "breakeven": len(breakeven),

        "winrate": (
            len(wins)
            / len(pnl)
            * 100
        ),

        "avg_win": avg_win,
        "avg_loss": avg_loss,
        "payoff_ratio": payoff_ratio,
        "breakeven_winrate": (
            breakeven_winrate
        ),

        "avg_pnl": pnl.mean(),
        "total_pnl": pnl.sum(),
        "profit_factor": profit_factor,
        "max_drawdown": max_drawdown,
    }

def replay_max_drawdown(
    data,
    pnl_col,
    time_col="entry_ts",
):
    if (
        data.empty
        or pnl_col not in data.columns
        or time_col not in data.columns
    ):
        return 0.0

    work = data.copy()

    work[pnl_col] = pd.to_numeric(
        work[pnl_col],
        errors="coerce",
    )

    work[time_col] = pd.to_datetime(
        work[time_col],
        utc=True,
        errors="coerce",
    )

    work = (
        work
        .dropna(subset=[pnl_col, time_col])
        .sort_values(time_col)
    )

    if work.empty:
        return 0.0

    equity = work[pnl_col].cumsum()

    equity = pd.concat(
        [
            pd.Series([0.0]),
            equity.reset_index(drop=True),
        ],
        ignore_index=True,
    )

    equity_peak = equity.cummax()
    drawdown = equity - equity_peak

    return float(drawdown.min())


def normalize_replay_bool(series):
    if pd.api.types.is_bool_dtype(series):
        return series.fillna(False)

    return (
        series
        .astype(str)
        .str.strip()
        .str.lower()
        .isin(["true", "1", "yes"])
    )

def compression_profit_factor(series):
    pnl = pd.to_numeric(series, errors="coerce").dropna()

    gross_profit = pnl[pnl > 0].sum()
    gross_loss = abs(pnl[pnl < 0].sum())

    if gross_loss == 0:
        return None

    return round(gross_profit / gross_loss, 2)


def build_compression_analytics_report(
    data: pd.DataFrame,
    group_cols: list[str],
    min_trades: int = 1,
) -> pd.DataFrame:
    """
    Builds a performance report for one or more compression dimensions.

    Examples:
        ["compression_shape"]
        ["compression_quality_label"]
        ["side", "compression_shape"]
        ["compression_shape", "compression_duration_bucket"]
    """

    required_cols = group_cols + ["pnl"]

    missing = [col for col in required_cols if col not in data.columns]

    if missing:
        return pd.DataFrame()

    work = data.copy()

    work["pnl"] = pd.to_numeric(work["pnl"], errors="coerce")

    for col in ["max_favorable_pct", "max_adverse_pct", "pnl_usd"]:
        if col in work.columns:
            work[col] = pd.to_numeric(work[col], errors="coerce")

    work = work.dropna(subset=group_cols + ["pnl"])

    if work.empty:
        return pd.DataFrame()

    aggregations = {
        "trades": ("pnl", "count"),
        "wins": ("pnl", lambda x: int((x > 0).sum())),
        "losses": ("pnl", lambda x: int((x <= 0).sum())),
        "winrate": (
            "pnl",
            lambda x: round((x > 0).mean() * 100, 2),
        ),
        "avg_pnl": ("pnl", "mean"),
        "total_pnl": ("pnl", "sum"),
        "median_pnl": ("pnl", "median"),
        "avg_win": (
            "pnl",
            lambda x: x[x > 0].mean() if (x > 0).any() else 0,
        ),
        "avg_loss": (
            "pnl",
            lambda x: x[x <= 0].mean() if (x <= 0).any() else 0,
        ),
        "profit_factor": ("pnl", compression_profit_factor),
    }

    if "max_favorable_pct" in work.columns:
        aggregations["avg_mfe"] = ("max_favorable_pct", "mean")

    if "max_adverse_pct" in work.columns:
        aggregations["avg_mae"] = ("max_adverse_pct", "mean")

    if "pnl_usd" in work.columns:
        aggregations["total_pnl_usd"] = ("pnl_usd", "sum")

    report = (
        work
        .groupby(group_cols, observed=False)
        .agg(**aggregations)
        .reset_index()
    )

    report = report[report["trades"] >= min_trades].copy()

    numeric_round_cols = [
        "avg_pnl",
        "total_pnl",
        "median_pnl",
        "avg_win",
        "avg_loss",
        "avg_mfe",
        "avg_mae",
        "total_pnl_usd",
    ]

    for col in numeric_round_cols:
        if col in report.columns:
            report[col] = report[col].round(4)

    if report.empty:
        return report

    report = report.sort_values(
        by=["profit_factor", "total_pnl", "winrate", "trades"],
        ascending=[False, False, False, False],
        na_position="last",
    )

    return report

def prepare_compression_outcome_df(
    data: pd.DataFrame,
) -> pd.DataFrame:

    if data.empty or "pnl" not in data.columns:
        return pd.DataFrame()

    out = data.copy()

    out["pnl"] = pd.to_numeric(
        out["pnl"],
        errors="coerce",
    )

    out = out.dropna(subset=["pnl"]).copy()

    # =========================
    # UNIQUE TRADE KEY
    # =========================

    if (
        "trade_id" in out.columns
        and out["trade_id"].notna().all()
        and out["trade_id"].astype(str).nunique() == len(out)
    ):
        out["trade_key"] = (
            out["trade_id"].astype(str)
        )

    elif all(
        col in out.columns
        for col in ["symbol", "entry_ts"]
    ):
        out["trade_key"] = (
            out["symbol"].astype(str)
            + "_"
            + out["entry_ts"].astype(str)
        )

    elif all(
        col in out.columns
        for col in ["symbol", "entry_ts_dt"]
    ):
        out["trade_key"] = (
            out["symbol"].astype(str)
            + "_"
            + out["entry_ts_dt"].astype(str)
        )

    else:
        out["trade_key"] = (
            "row_" + out.index.astype(str)
        )

    # Evitar que un trade duplicado altere las estadísticas.
    out = out.drop_duplicates(
        subset=["trade_key"],
        keep="first",
    ).copy()

    # =========================
    # TP / SL OUTCOME
    # =========================

    if "exit_reason" not in out.columns:
        out["compression_outcome"] = "OTHER"
        return out

    exit_reason = (
        out["exit_reason"]
        .fillna("")
        .astype(str)
        .str.strip()
    )

    # =========================
    # TP / SL OUTCOME
    # =========================

    if "exit_reason" not in out.columns:
        out["compression_outcome"] = "OTHER"
        return out

    exit_reason = (
        out["exit_reason"]
        .fillna("")
        .astype(str)
        .str.strip()
        .str.upper()
    )

    is_tp = (
        exit_reason.eq("TP")
        | exit_reason.str.contains(
            r"TAKE[_ ]?PROFIT",
            regex=True,
            na=False,
        )
    )

    is_sl = (
        exit_reason.eq("SL")
        | exit_reason.str.contains(
            r"STOP[_ ]?LOSS",
            regex=True,
            na=False,
        )
    )

    out["compression_outcome"] = np.select(
        [
            is_tp,
            is_sl,
        ],
        [
            "TP",
            "SL",
        ],
        default="OTHER",
    )

    # =========================
    # ENTRY DATETIME
    # =========================

    if "entry_ts_dt" in out.columns:
        out["outcome_entry_datetime"] = pd.to_datetime(
            out["entry_ts_dt"],
            errors="coerce",
            utc=True,
        )

    elif "entry_ts" in out.columns:
        numeric_entry_ts = pd.to_numeric(
            out["entry_ts"],
            errors="coerce",
        )

        out["outcome_entry_datetime"] = pd.to_datetime(
            numeric_entry_ts,
            unit="ms",
            errors="coerce",
            utc=True,
        )

        missing_datetime = (
            out["outcome_entry_datetime"].isna()
        )

        if missing_datetime.any():
            out.loc[
                missing_datetime,
                "outcome_entry_datetime",
            ] = pd.to_datetime(
                out.loc[
                    missing_datetime,
                    "entry_ts",
                ],
                errors="coerce",
                utc=True,
            )

    else:
        out["outcome_entry_datetime"] = pd.NaT

    out["outcome_entry_date"] = (
        out["outcome_entry_datetime"].dt.date
    )

    out["outcome_entry_30m"] = (
        out["outcome_entry_datetime"]
        .dt.floor("30min")
    )

    return out

def build_outcome_numeric_comparison(
    data: pd.DataFrame,
    feature_cols: list[str],
) -> pd.DataFrame:

    rows = []

    for feature in feature_cols:
        if feature not in data.columns:
            continue

        work = data[
            [
                "compression_outcome",
                feature,
            ]
        ].copy()

        work[feature] = pd.to_numeric(
            work[feature],
            errors="coerce",
        )

        work = work.dropna(subset=[feature])

        tp_values = work.loc[
            work["compression_outcome"] == "TP",
            feature,
        ]

        sl_values = work.loc[
            work["compression_outcome"] == "SL",
            feature,
        ]

        if tp_values.empty or sl_values.empty:
            continue

        all_values = pd.concat(
            [
                tp_values,
                sl_values,
            ]
        )

        pooled_std = all_values.std(ddof=0)

        mean_difference = (
            tp_values.mean()
            - sl_values.mean()
        )

        standardized_difference = (
            mean_difference / pooled_std
            if pd.notna(pooled_std) and pooled_std > 0
            else np.nan
        )

        rows.append({
            "feature": feature,

            "tp_trades": len(tp_values),
            "sl_trades": len(sl_values),

            "coverage_pct": (
                len(work) / len(data) * 100
                if len(data) > 0
                else 0
            ),

            "tp_mean": tp_values.mean(),
            "sl_mean": sl_values.mean(),
            "mean_difference_tp_minus_sl": (
                mean_difference
            ),

            "tp_median": tp_values.median(),
            "sl_median": sl_values.median(),
            "median_difference_tp_minus_sl": (
                tp_values.median()
                - sl_values.median()
            ),

            "standardized_difference": (
                standardized_difference
            ),
        })

    if not rows:
        return pd.DataFrame()

    report = pd.DataFrame(rows)

    report["abs_standardized_difference"] = (
        report["standardized_difference"].abs()
    )

    numeric_cols = [
        "coverage_pct",
        "tp_mean",
        "sl_mean",
        "mean_difference_tp_minus_sl",
        "tp_median",
        "sl_median",
        "median_difference_tp_minus_sl",
        "standardized_difference",
        "abs_standardized_difference",
    ]

    report[numeric_cols] = (
        report[numeric_cols].round(4)
    )

    return report.sort_values(
        [
            "abs_standardized_difference",
            "coverage_pct",
        ],
        ascending=[
            False,
            False,
        ],
        na_position="last",
    )
    
def build_compression_outcome_bucket_report(
    data: pd.DataFrame,
    group_cols: list[str],
    min_trades: int = 1,
) -> pd.DataFrame:

    required_cols = (
        group_cols
        + [
            "trade_key",
            "compression_outcome",
            "pnl",
        ]
    )

    missing_cols = [
        col
        for col in required_cols
        if col not in data.columns
    ]

    if missing_cols:
        return pd.DataFrame()

    work = data.copy()

    work = work[
        work["compression_outcome"]
        .isin(["TP", "SL"])
    ].copy()

    work["pnl"] = pd.to_numeric(
        work["pnl"],
        errors="coerce",
    )

    work = work.dropna(
        subset=group_cols + ["pnl"]
    )

    if work.empty:
        return pd.DataFrame()

    aggregations = {
        "trades": (
            "trade_key",
            "nunique",
        ),
        "tp": (
            "compression_outcome",
            lambda x: int((x == "TP").sum()),
        ),
        "sl": (
            "compression_outcome",
            lambda x: int((x == "SL").sum()),
        ),
        "avg_pnl": (
            "pnl",
            "mean",
        ),
        "median_pnl": (
            "pnl",
            "median",
        ),
        "total_pnl": (
            "pnl",
            "sum",
        ),
        "profit_factor": (
            "pnl",
            compression_profit_factor,
        ),
    }

    if "symbol" in work.columns:
        aggregations["unique_symbols"] = (
            "symbol",
            "nunique",
        )

    if "outcome_entry_date" in work.columns:
        aggregations["unique_days"] = (
            "outcome_entry_date",
            "nunique",
        )

    if "outcome_entry_30m" in work.columns:
        aggregations["unique_batches"] = (
            "outcome_entry_30m",
            "nunique",
        )

    report = (
        work
        .groupby(
            group_cols,
            observed=False,
        )
        .agg(**aggregations)
        .reset_index()
    )

    report = report[
        report["trades"] >= min_trades
    ].copy()

    if report.empty:
        return report

    report["tp_rate"] = (
        report["tp"]
        / report["trades"]
        * 100
    ).round(2)

    report["sl_rate"] = (
        report["sl"]
        / report["trades"]
        * 100
    ).round(2)

    for col in [
        "avg_pnl",
        "median_pnl",
        "total_pnl",
    ]:
        report[col] = report[col].round(4)

    return report.sort_values(
        [
            "profit_factor",
            "total_pnl",
            "trades",
        ],
        ascending=[
            False,
            False,
            False,
        ],
        na_position="last",
    )
    
def build_compression_confluence_report(
    df,
    row_dimension,
    column_dimension,
    min_trades=10,
):
    """
    Compara resultados TP/SL cruzando dos dimensiones.

    Ejemplo:
        compression_height_bucket
        x breakout_extension_atr_bucket
    """

    required_cols = [
        row_dimension,
        column_dimension,
        "compression_outcome",
        "pnl",
    ]

    if (
        df is None
        or df.empty
        or any(
            col not in df.columns
            for col in required_cols
        )
    ):
        return pd.DataFrame()

    work = df[
        required_cols
    ].copy()

    work["pnl"] = pd.to_numeric(
        work["pnl"],
        errors="coerce",
    )

    work = work[
        work["compression_outcome"]
        .isin(["TP", "SL"])
    ].copy()

    work = work.dropna(
        subset=[
            row_dimension,
            column_dimension,
            "pnl",
        ]
    )

    if work.empty:
        return pd.DataFrame()

    total_available_trades = len(work)
    report_rows = []

    grouped = work.groupby(
        [
            row_dimension,
            column_dimension,
        ],
        observed=True,
        dropna=False,
    )

    for (
        row_value,
        column_value,
    ), group_df in grouped:

        trades = len(group_df)

        if trades < min_trades:
            continue

        tp_mask = (
            group_df["compression_outcome"]
            .eq("TP")
        )

        sl_mask = (
            group_df["compression_outcome"]
            .eq("SL")
        )

        tp_count = int(tp_mask.sum())
        sl_count = int(sl_mask.sum())

        wins = group_df.loc[
            tp_mask,
            "pnl",
        ]

        losses = group_df.loc[
            sl_mask,
            "pnl",
        ]

        gross_profit = wins[
            wins > 0
        ].sum()

        gross_loss = abs(
            losses[
                losses < 0
            ].sum()
        )

        if gross_loss > 0:
            profit_factor = (
                gross_profit / gross_loss
            )
        elif gross_profit > 0:
            profit_factor = float("inf")
        else:
            profit_factor = None

        avg_win = (
            wins.mean()
            if not wins.empty
            else None
        )

        avg_loss = (
            losses.mean()
            if not losses.empty
            else None
        )

        report_rows.append({
            row_dimension: row_value,
            column_dimension: column_value,

            "trades": trades,
            "tp": tp_count,
            "sl": sl_count,

            "tp_rate": (
                tp_count / trades * 100
                if trades
                else 0.0
            ),

            "avg_win": avg_win,
            "avg_loss": avg_loss,

            "avg_pnl": (
                group_df["pnl"].mean()
            ),

            "median_pnl": (
                group_df["pnl"].median()
            ),

            "total_pnl": (
                group_df["pnl"].sum()
            ),

            "profit_factor": profit_factor,

            "coverage_pct": (
                trades
                / total_available_trades
                * 100
            ),
        })

    if not report_rows:
        return pd.DataFrame()

    report = pd.DataFrame(
        report_rows
    )

    numeric_cols = [
        "tp_rate",
        "avg_win",
        "avg_loss",
        "avg_pnl",
        "median_pnl",
        "total_pnl",
        "profit_factor",
        "coverage_pct",
    ]

    for col in numeric_cols:
        report[col] = pd.to_numeric(
            report[col],
            errors="coerce",
        ).round(4)

    report = report.sort_values(
        by=[
            "profit_factor",
            "trades",
        ],
        ascending=[
            False,
            False,
        ],
        na_position="last",
    ).reset_index(drop=True)

    return report
    
def summarize_compression_outcome(
    data: pd.DataFrame,
) -> dict:

    pnl = pd.to_numeric(
        data["pnl"],
        errors="coerce",
    ).dropna()

    tp = int(
        (
            data["compression_outcome"]
            == "TP"
        ).sum()
    )

    sl = int(
        (
            data["compression_outcome"]
            == "SL"
        ).sum()
    )

    decided_trades = tp + sl

    return {
        "trades": len(pnl),
        "tp": tp,
        "sl": sl,

        "tp_rate": (
            tp / decided_trades * 100
            if decided_trades > 0
            else 0
        ),

        "avg_pnl": (
            pnl.mean()
            if not pnl.empty
            else 0
        ),

        "total_pnl": (
            pnl.sum()
            if not pnl.empty
            else 0
        ),

        "profit_factor": (
            compression_profit_factor(pnl)
        ),
    }

def add_compression_analytics_buckets(data: pd.DataFrame) -> pd.DataFrame:
    """
    Creates categorical buckets without modifying the original dataframe.
    """

    out = data.copy()

    numeric_cols = [
        # Detector
        "compression_score",
        "range_ratio",
        "atr_ratio",
        "volume_ratio",
        "avg_body_pct",
        "compression_range_pct",

        # Structure
        "compression_height_pct",
        "compression_duration",
        "upper_slope",
        "lower_slope",
        "slope_difference",
        "touches_high",
        "touches_low",
        "inside_ratio",
        
        # Breakout
        "breakout_volume_ratio",
        "breakout_extension_pct",
        "breakout_extension_atr",

        # Entry
        "entry_distance_pct",
        "entry_vs_compression_pct",
        "entry_vs_breakout_pct",
        "entry_ready_vs_breakout_pct",
    ]

    for col in numeric_cols:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce")
            
    # =========================
    # DETECTOR COMPONENTS
    # =========================

    # Compression score: cantidad de condiciones cumplidas
    if "compression_score" in out.columns:
        out["compression_score_bucket"] = pd.cut(
            out["compression_score"],
            bins=[-np.inf, 0.5, 1.5, 2.5, 3.5, 4.5, np.inf],
            labels=[
                "Score 0",
                "Score 1",
                "Score 2",
                "Score 3",
                "Score 4",
                "Score > 4",
            ],
        )

    # Contracción del rango
    if "range_ratio" in out.columns:
        out["range_ratio_bucket"] = pd.cut(
            out["range_ratio"],
            bins=[
                -np.inf,
                0.50,
                0.65,
                0.75,
                0.85,
                1.00,
                np.inf,
            ],
            labels=[
                "<= 0.50",
                "0.50 - 0.65",
                "0.65 - 0.75",
                "0.75 - 0.85",
                "0.85 - 1.00",
                "> 1.00",
            ],
        )

    # Contracción del ATR
    if "atr_ratio" in out.columns:
        out["atr_ratio_bucket"] = pd.cut(
            out["atr_ratio"],
            bins=[
                -np.inf,
                0.50,
                0.65,
                0.75,
                0.85,
                1.00,
                np.inf,
            ],
            labels=[
                "<= 0.50",
                "0.50 - 0.65",
                "0.65 - 0.75",
                "0.75 - 0.85",
                "0.85 - 1.00",
                "> 1.00",
            ],
        )

    # Comportamiento del volumen durante la compresión
    if "volume_ratio" in out.columns:
        out["volume_ratio_bucket"] = pd.cut(
            out["volume_ratio"],
            bins=[
                -np.inf,
                0.60,
                0.80,
                1.00,
                1.10,
                1.30,
                np.inf,
            ],
            labels=[
                "<= 0.60",
                "0.60 - 0.80",
                "0.80 - 1.00",
                "1.00 - 1.10",
                "1.10 - 1.30",
                "> 1.30",
            ],
        )

    # Cuerpo promedio respecto del rango de cada vela
    if "avg_body_pct" in out.columns:
        out["avg_body_pct_bucket"] = pd.cut(
            out["avg_body_pct"],
            bins=[
                -np.inf,
                0.25,
                0.35,
                0.45,
                0.55,
                0.70,
                np.inf,
            ],
            labels=[
                "<= 0.25",
                "0.25 - 0.35",
                "0.35 - 0.45",
                "0.45 - 0.55",
                "0.55 - 0.70",
                "> 0.70",
            ],
        )

    # Altura total del rango respecto del precio
    if "compression_range_pct" in out.columns:
        out["compression_range_pct_bucket"] = pd.cut(
            out["compression_range_pct"],
            bins=[
                -np.inf,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                3.00,
                5.00,
                np.inf,
            ],
            labels=[
                "<= 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "2.00% - 3.00%",
                "3.00% - 5.00%",
                "> 5.00%",
            ],
        )

    # =========================
    # COMPRESSION DURATION
    # =========================
    if "compression_duration" in out.columns:
        out["compression_duration_bucket"] = pd.cut(
            out["compression_duration"],
            bins=[-np.inf, 5, 10, 15, 20, 30, 50, np.inf],
            labels=[
                "<= 5",
                "6 - 10",
                "11 - 15",
                "16 - 20",
                "21 - 30",
                "31 - 50",
                "> 50",
            ],
        )

    # =========================
    # COMPRESSION HEIGHT %
    # =========================
    if "compression_height_pct" in out.columns:
        out["compression_height_bucket"] = pd.cut(
            out["compression_height_pct"],
            bins=[
                -np.inf,
                0.25,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                3.00,
                np.inf,
            ],
            labels=[
                "<= 0.25%",
                "0.25% - 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "2.00% - 3.00%",
                "> 3.00%",
            ],
        )

    # =========================
    # INSIDE RATIO
    # =========================
    if "inside_ratio" in out.columns:
        out["inside_ratio_bucket"] = pd.cut(
            out["inside_ratio"],
            bins=[
                -np.inf,
                0.50,
                0.60,
                0.70,
                0.80,
                0.90,
                0.95,
                np.inf,
            ],
            labels=[
                "<= 0.50",
                "0.50 - 0.60",
                "0.60 - 0.70",
                "0.70 - 0.80",
                "0.80 - 0.90",
                "0.90 - 0.95",
                "> 0.95",
            ],
        )

    # =========================
    # TOUCHES
    # =========================
    if "touches_high" in out.columns and "touches_low" in out.columns:
        out["total_touches"] = (
            out["touches_high"].fillna(0)
            + out["touches_low"].fillna(0)
        )

        out["total_touches_bucket"] = pd.cut(
            out["total_touches"],
            bins=[-np.inf, 2, 3, 4, 5, 6, 8, np.inf],
            labels=[
                "<= 2",
                "3",
                "4",
                "5",
                "6",
                "7 - 8",
                "> 8",
            ],
        )

        out["touch_balance"] = (
            out["touches_high"] - out["touches_low"]
        ).abs()
        
        out["touch_imbalance_signed"] = (
            out["touches_high"]
            - out["touches_low"]
        )

        out["touch_imbalance_direction"] = pd.cut(
            out["touch_imbalance_signed"],
            bins=[
                -np.inf,
                -2.5,
                -1.5,
                -0.5,
                0.5,
                1.5,
                2.5,
                np.inf,
            ],
            labels=[
                "More Low Touches > 2",
                "More Low Touches 2",
                "More Low Touches 1",
                "Balanced",
                "More High Touches 1",
                "More High Touches 2",
                "More High Touches > 2",
            ],
        )

        out["touch_balance_bucket"] = pd.cut(
            out["touch_balance"],
            bins=[-np.inf, 0, 1, 2, np.inf],
            labels=[
                "Balanced",
                "Difference 1",
                "Difference 2",
                "Difference > 2",
            ],
        )

    # =========================
    # SLOPE MAGNITUDE
    # =========================
    if "upper_slope" in out.columns:
        out["upper_slope_abs"] = out["upper_slope"].abs()

        out["upper_slope_bucket"] = pd.cut(
            out["upper_slope_abs"],
            bins=[-np.inf, 0.02, 0.05, 0.10, 0.20, np.inf],
            labels=[
                "Flat",
                "Very Low",
                "Low",
                "Medium",
                "High",
            ],
        )

    if "lower_slope" in out.columns:
        out["lower_slope_abs"] = out["lower_slope"].abs()

        out["lower_slope_bucket"] = pd.cut(
            out["lower_slope_abs"],
            bins=[-np.inf, 0.02, 0.05, 0.10, 0.20, np.inf],
            labels=[
                "Flat",
                "Very Low",
                "Low",
                "Medium",
                "High",
            ],
        )

    if "slope_difference" in out.columns:
        out["slope_difference_abs"] = out["slope_difference"].abs()

        out["slope_difference_bucket"] = pd.cut(
            out["slope_difference_abs"],
            bins=[-np.inf, 0.02, 0.05, 0.10, 0.20, np.inf],
            labels=[
                "Very Similar",
                "Similar",
                "Moderate Difference",
                "Large Difference",
                "Very Large Difference",
            ],
        )

    # =========================
    # BREAKOUT QUALITY
    # =========================

    # Volumen de la vela de breakout respecto del volumen de referencia
    if "breakout_volume_ratio" in out.columns:
        out["breakout_volume_ratio_bucket"] = pd.cut(
            out["breakout_volume_ratio"],
            bins=[
                -np.inf,
                0.75,
                1.00,
                1.25,
                1.50,
                2.00,
                3.00,
                np.inf,
            ],
            labels=[
                "<= 0.75x",
                "0.75x - 1.00x",
                "1.00x - 1.25x",
                "1.25x - 1.50x",
                "1.50x - 2.00x",
                "2.00x - 3.00x",
                "> 3.00x",
            ],
        )

    # Extensión porcentual alcanzada por el breakout
    if "breakout_extension_pct" in out.columns:
        out["breakout_extension_pct_bucket"] = pd.cut(
            out["breakout_extension_pct"],
            bins=[
                -np.inf,
                0,
                0.25,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                np.inf,
            ],
            labels=[
                "<= 0%",
                "0% - 0.25%",
                "0.25% - 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "> 2.00%",
            ],
        )

    # =========================
    # ENTRY LOCATION
    # =========================
    entry_bucket_configs = {
        "entry_distance_pct": "entry_distance_bucket_analytics",
        "entry_vs_compression_pct": "entry_vs_compression_bucket",
    }

    for source_col, bucket_col in entry_bucket_configs.items():
        if source_col not in out.columns:
            continue

        out[bucket_col] = pd.cut(
            out[source_col],
            bins=[
                -np.inf,
                0,
                0.10,
                0.25,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                np.inf,
            ],
            labels=[
                "< 0%",
                "0% - 0.10%",
                "0.10% - 0.25%",
                "0.25% - 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "> 2.00%",
            ],
        )

    # =========================
    # ENTRY VS BREAKOUT
    # =========================
    if "entry_vs_breakout_pct" in out.columns:
        out["entry_vs_breakout_bucket"] = pd.cut(
            out["entry_vs_breakout_pct"],
            bins=[
                -np.inf,
                -1.00,
                -0.50,
                -0.25,
                -0.10,
                0,
                0.10,
                0.25,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                np.inf,
            ],
            labels=[
                "< -1.00%",
                "-1.00% - -0.50%",
                "-0.50% - -0.25%",
                "-0.25% - -0.10%",
                "-0.10% - 0%",
                "0% - 0.10%",
                "0.10% - 0.25%",
                "0.25% - 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "> 2.00%",
            ],
        )
        
    # =========================
    # ENTRY READY VS BREAKOUT
    # Forward-safe: conocida antes de ejecutar
    # =========================
    if "entry_ready_vs_breakout_pct" in out.columns:
        out["entry_ready_vs_breakout_bucket"] = pd.cut(
            out["entry_ready_vs_breakout_pct"],
            bins=[
                -np.inf,
                -1.00,
                -0.50,
                -0.25,
                -0.10,
                0,
                0.10,
                0.25,
                0.50,
                0.75,
                1.00,
                1.50,
                2.00,
                np.inf,
            ],
            labels=[
                "< -1.00%",
                "-1.00% - -0.50%",
                "-0.50% - -0.25%",
                "-0.25% - -0.10%",
                "-0.10% - 0%",
                "0% - 0.10%",
                "0.10% - 0.25%",
                "0.25% - 0.50%",
                "0.50% - 0.75%",
                "0.75% - 1.00%",
                "1.00% - 1.50%",
                "1.50% - 2.00%",
                "> 2.00%",
            ],
        )

    # Normalize boolean for grouping
    if "late_entry" in out.columns:
        out["late_entry_label"] = (
            out["late_entry"]
            .astype(str)
            .str.lower()
            .map({
                "true": "Late Entry",
                "false": "Normal Entry",
                "1": "Late Entry",
                "0": "Normal Entry",
            })
            .fillna("Unknown")
        )

    return out


@st.cache_data(show_spinner=False)
def add_compression_analytics_buckets_cached(
    data: pd.DataFrame,
) -> pd.DataFrame:
    """
    Bucket enrichment is deterministic and relatively expensive.
    Streamlit reuses it until the input dataframe changes.
    """
    return add_compression_analytics_buckets(data)


@st.cache_data(show_spinner=False)
def build_candidate_bucket_trades_cached(
    data: pd.DataFrame,
    bucket_definition_json: str,
) -> pd.DataFrame:
    bucket_definition = json.loads(
        bucket_definition_json
    )

    bucket_source = (
        add_compression_analytics_buckets(data)
    )

    bucket_trades = (
        filter_by_replay_bucket_definition(
            bucket_source,
            bucket_definition,
        )
    )

    if bucket_trades.empty:
        return bucket_trades

    bucket_trades["replay_trade_key"] = (
        build_replay_trade_keys(bucket_trades)
    )

    entry_source = (
        bucket_trades["entry_ts_dt"]
        if "entry_ts_dt" in bucket_trades.columns
        else bucket_trades.get("entry_ts")
    )

    bucket_trades["candidate_entry_ts"] = (
        pd.to_datetime(
            entry_source,
            utc=True,
            errors="coerce",
        )
    )

    return (
        bucket_trades
        .dropna(subset=[
            "replay_trade_key",
            "candidate_entry_ts",
        ])
        .drop_duplicates(
            subset=["replay_trade_key"],
            keep="first",
        )
        .copy()
    )


@st.cache_data(ttl=60, show_spinner=False)
def build_candidate_scenarios_cached(
    scenarios: pd.DataFrame,
    observation_minutes: int,
    tp_target_pct: float,
    sl_buffer_pct: float,
) -> pd.DataFrame:
    cutoff = (
        pd.Timestamp.now(tz="UTC")
        - pd.Timedelta(
            minutes=observation_minutes
        )
    )

    work = scenarios[
        scenarios["exit_ts"].le(cutoff)
    ].copy()

    required_columns = [
        "sl_mode",
        "result",
        "tp_target_pct",
        "sl_buffer_pct",
        "structural_risk_pct",
        "simulated_pnl_pct",
        "original_pnl",
        "replay_trade_key",
    ]

    if any(
        column not in work.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    work["sl_mode"] = (
        work["sl_mode"]
        .fillna("")
        .astype(str)
        .str.upper()
    )
    work["result"] = (
        work["result"]
        .fillna("")
        .astype(str)
        .str.upper()
    )

    return (
        work[
            work["sl_mode"].eq("STRUCTURAL")
            & work["result"].isin(["TP", "SL"])
            & np.isclose(
                work["tp_target_pct"],
                tp_target_pct,
            )
            & np.isclose(
                work["sl_buffer_pct"],
                sl_buffer_pct,
            )
            & work["structural_risk_pct"].gt(0)
            & work["simulated_pnl_pct"].notna()
            & work["original_pnl"].notna()
        ]
        .sort_values("entry_ts")
        .drop_duplicates(
            subset=["replay_trade_key"],
            keep="first",
        )
        .copy()
    )


def build_btc_direction_matrix(df: pd.DataFrame) -> pd.DataFrame:
    required_cols = [
        "side",
        "btc_direction_1h",
        "btc_direction_15m",
        "pnl",
    ]

    missing = [c for c in required_cols if c not in df.columns]
    if missing:
        return pd.DataFrame()

    data = df.copy()

    data["side"] = data["side"].astype(str).str.upper().str.strip()
    data["btc_direction_1h"] = data["btc_direction_1h"].astype(str).str.upper().str.strip()
    data["btc_direction_15m"] = data["btc_direction_15m"].astype(str).str.upper().str.strip()
    data["pnl"] = pd.to_numeric(data["pnl"], errors="coerce")

    data = data.dropna(subset=["side", "btc_direction_1h", "btc_direction_15m", "pnl"])

    matrix = (
        data
        .groupby(["btc_direction_1h", "btc_direction_15m", "side"])
        .agg(
            trades=("pnl", "count"),
            wins=("pnl", lambda x: int((x > 0).sum())),
            losses=("pnl", lambda x: int((x <= 0).sum())),
            winrate=("pnl", lambda x: round((x > 0).mean() * 100, 2)),
            avg_pnl=("pnl", "mean"),
            total_pnl=("pnl", "sum"),
            avg_win=("pnl", lambda x: round(x[x > 0].mean(), 3) if (x > 0).any() else 0),
            avg_loss=("pnl", lambda x: round(x[x <= 0].mean(), 3) if (x <= 0).any() else 0),
            pf=("pnl", profit_factor),
        )
        .reset_index()
    )

    for col in ["avg_pnl", "total_pnl"]:
        matrix[col] = matrix[col].round(3)

    return matrix


def build_btc_direction_pivot(matrix: pd.DataFrame) -> pd.DataFrame:
    if matrix.empty:
        return pd.DataFrame()

    pivot = matrix.pivot_table(
        index=["btc_direction_1h", "btc_direction_15m"],
        columns="side",
        values=["trades", "winrate", "avg_pnl", "total_pnl", "pf"],
        fill_value=0,
    )

    pivot.columns = [f"{metric}_{side}" for metric, side in pivot.columns]
    pivot = pivot.reset_index()

    return pivot

